"""Author Week 1 as a connected reading journey; preserve all existing blocks.
The main route, within-section chunks and reference bank are explicit editorial
choices. This is deliberately a one-week pilot, not a whole-programme template.
"""
from pathlib import Path
import json,copy,re
R=Path(__file__).resolve().parents[1];p=R/'content/programme.json';d=json.loads(p.read_text());w=d['weeks'][0]
assert w['id']=='ai-1/1'
if w['sections'][0].get('reading_flow'):raise SystemExit('Week 1 reading design already applied; edit the authored metadata directly.')
original=copy.deepcopy(w)

def add(role,section,text=None,label=None,image=None):
 s=w[role][section-1]
 b=copy.deepcopy(image) if image else {'type':'paragraph','text':text,'presentation':{'kind':'body','paragraphs':[text],'emphasis':[]}}
 if label:b['presentation']['label']=label
 b['reading_addition']='week1-connected-reading'
 s['blocks'].append(b);return len(s['blocks'])-1

def picture(n):return next(b for b in w['sections'][-1]['blocks'] if b.get('src','').endswith(f'academy-story-ai-1-1-{n:02}'))
def group(title,indices,kind='text',note=None,collapsed=False):
 return {'title':title,'kind':kind,'indices':indices,**({'note':note} if note else {}),**({'collapsed':True} if collapsed else {})}
def design(role,n,title,purpose,groups,extra,optional=False):
 s=w[role][n-1];used=[i for g in groups for i in g['indices']];assert len(used)==len(set(used)),(role,n)
 remaining=[i for i in range(len(s['blocks'])) if i not in used]
 if remaining:groups.append(group(extra,remaining,'reference',collapsed=True))
 s['reading_flow']={'title':title,'purpose':purpose,'optional':optional,'groups':groups}
 assert sorted(i for g in groups for i in g['indices'])==list(range(len(s['blocks'])))

# Student: one question connects the clock, bus, umbrella and photo-library cases.
clock=add('sections',1,'A clock says the correct time. Hearing it tells you what it did. It does not yet tell you how it did it. Keep that distinction in mind throughout this week.')
design('sections',1,'What makes a machine seem clever?','Your goal: explain how a decision was made, using a fact about the process.',[group('Start with one small puzzle',[clock,6],'example'),group('By the end, you can…',[1,2,3],'prompts'),group('How to use this week',[5,7])],'Earlier target wording and repeated recall')
bus_pic=add('sections',2,image=picture(1))
design('sections',2,'A red bus display: what do we really know?','First describe what you can see. Then look for evidence about what happened inside.',[group('Meet Leila and Arun',[13],'example'),group('Look before you explain',[bus_pic,14]),group('Read the builder’s notes',[15],'example',note='These notes are given facts for our fictional case. They are stronger mechanism evidence than the colour of the display.'),group('Your first observations',[6,7,8,9],'prompts')],'Extra observation prompts and original picture-story notes')
mechanism_pic=add('sections',3,image=picture(3))
mechanisms=[add('sections',3,'Earlier journeys were used to fit the delay model. It uses today’s route and traffic information to estimate a 12-minute delay. A prediction can be wrong.',label='1. Predict a number'),add('sections',3,'A person wrote this instruction: turn the display red when the estimated delay is greater than 10 minutes. Twelve is greater than ten, so the display turns red.',label='2. Apply a written rule'),add('sections',3,'The driver can choose a replacement message, such as ROUTE CLOSED. That replacement is a human decision.',label='3. Make a human choice')]
design('sections',3,'One product, three different decisions','Follow the number, the colour and the driver’s message separately.',[group('Read the whole system',[mechanism_pic]),group('Explain each decision',mechanisms,'cards'),group('Trace an information path',[6,7,8],'steps'),group('Keep this important distinction',[15],'example',note='A written rule is not automatically outside AI. This particular colour switch is simple automation; AI can also use symbolic reasoning.'),group('Explain one arrow',[17],'prompts')],'Full bus table and further mechanism explanation')
# Match each small illustration to its own evidence text, instead of four images then four captions.
case_gallery={'type':'gallery','layout':'reading-cards','cells':[[copy.deepcopy(w['sections'][3]['blocks'][3+i]),copy.deepcopy(w['sections'][3]['blocks'][7+i])] for i in range(4)],'reading_addition':'week1-connected-reading'}
w['sections'][3]['blocks'].append(case_gallery);ci=len(w['sections'][3]['blocks'])-1
design('sections',4,'Compare the evidence, not the appearance','Ask who or what chooses the action in each case.',[group('Four mechanisms to compare',[ci],'cards'),group('Discuss with a partner',[12],'prompts'),group('A limit to remember',[11],'example')],'Original comparison cards and umbrella extension')
design('sections',5,'Your quick word guide','Return here when a word blocks your explanation; you do not need to memorise both tables.',[group('Useful words in this week’s cases',[13,7]),group('Use a word to repair a claim',[9,10],'prompts')],'Vocabulary badges and original teaching notes',True)
learn_pic=add('sections',6,image=picture(4));boundary_pic=add('sections',6,image=picture(5))
design('sections',6,'Work through the umbrella display','The forecast and the display rule do different jobs. Change one while keeping the other fixed.',[group('The case and its given facts',[18,20,21],'example'),group('First learn; later predict',[learn_pic]),group('Trace the four stages',[22,23]),group('Why the answer follows',[25]),group('Keep the forecast at 70%; change the rule',[boundary_pic,29],'example'),group('What this cannot prove',[27],'example'),group('Explain the deciding step',[28],'prompts')],'Bus reasoning recap and earlier worked-example prompts')
design('sections',7,'Repair a tempting explanation','A robot body, a screen or a correct answer does not reveal the decision mechanism.',[group('Try two repairs',[5,7,9],'prompts'),group('What if the mechanism is unknown?',[11,12]),group('Explain without guessing',[13],'prompts')],'Comparison table and earlier repair prompts')
photo=add('sections',8,'Use three rows: prediction → album placement → owner move. For each row, write who or what made that decision and the fact that tells you. If a photo is misplaced, check the intermediate prediction before deciding where the error occurred.')
design('sections',8,'Your turn: explain a photo library','Practise with help, then explain the evidence in your own words.',[group('Read the case',[11],'example'),group('Complete the explanation',[photo,13],'steps'),group('Investigate a wrong album',[12]),group('Challenge one generalisation',[19,20],'prompts'),group('Check your explanation with a partner',[9,17])],'Umbrella practice and additional guided prompts')
cards=add('sections',9,'Use these six fictional cards: a lamp triggered by a written motion rule; a photo sorter fitted on labelled pictures; a car steered by a person; a calculator following arithmetic instructions; a smart speaker with no process notes; and a robot vacuum with no process notes. For the last two, the mechanism has deliberately not been supplied.')
design('sections',9,'Investigate: become a device detective','Use the supplied cards. Record what you predict, what the given facts support, and what is still unknown.',[group('Your case cards',[cards],'example'),group('Run the investigation',[4,5,6,7,8],'steps'),group('Keep your evidence separate',[9,12]),group('After you have tried',[10],'example',note='Use the six-device worked explanation in the reference bank to discuss your result. A discussion case is practice, not a fresh assessment.')],'Original lab illustration and headings')
design('sections',10,'Choose a harder thinking challenge','Use one challenge when you are ready; these are options rather than six more compulsory tasks.',[group('Choose your next challenge',list(range(4,11)),'prompts')],'Practice-ladder illustration and coaching note',True)
design('sections',11,'Start your Helpful Classroom Sorter','Choose one real need, then justify the simplest process that could meet it.',[group('Make one design decision',[4,14],'example'),group('Plan your evidence',[5,6,7,8,9],'prompts'),group('Keep the boundary clear',[11])],'Project illustration, original heading and record label')
design('sections',12,'A checklist for explaining any new case','Use this as a reference after practice. The greenhouse is this week’s selected independent case.',[group('Check an explanation',[5,6,7,8,9],'prompts'),group('Think about your support',[12])],'Original six-device assessment wording and extra notes',True)
design('sections',13,'Check the six-device investigation','Open this after attempting the device detective task. It is a worked explanation.',[group('Question and explanation',[3,5,7],'example'),group('What the explanation does and does not establish',[11]),group('Explain your reasoning',[9,10],'prompts')],'Repeated six-device table and wording',True)
design('sections',14,'Explain a fresh case on your own','Use the greenhouse facts. Give one first attempt before hints or feedback.',[group('The greenhouse challenge',[1,2],'example'),group('Record your support',[3,22])],'Other transfer questions for later practice')
design('sections',15,'Reference: the original lesson route','The main route at the start of this edition replaces the need to follow several overlapping plans.',[group('Goals and evidence',[1,2,3])],'Original umbrella opening question',True)
design('sections',16,'Finish with one explanation you can defend','Close your notes, explain the idea, then decide what evidence to keep.',[group('Say it without the page',[0,1],'prompts'),group('Choose your next move',[2,3])],'Earlier reflection wording')
design('sections',17,'Optional supported practice','Choose the interactive questions or this paper version. They refer to the same practice, not two separate assignments.',[group('Question 1: identify the deciding stage',list(range(1,10)),'prompts'),group('Check after your attempt',[10],'example',collapsed=True),group('Question 2: change the boundary',list(range(11,18)),'prompts'),group('Check after your attempt',[18],'example',collapsed=True),group('Keep the work you completed',[20,22])],'Original practice and portfolio headings',True)
sg=[]
for n in range(6):sg.append(group(w['sections'][17]['blocks'][4*n]['text'],list(range(4*n+1,4*n+4))))
design('sections',18,'The six-picture reference gallery','Revisit a picture when you need it. Key pictures also appear beside the main explanation.',sg,'Original graphic headings',True)

# Teacher: preparation -> explanation -> guided response -> investigation -> evidence -> follow-up.
design('teacher',1,'Prepare this week','One learning aim, one main teaching plan, and a clear boundary between practice and independent evidence.',[group('What learners must understand',[1,17,24]),group('What to prepare',[14,20,21,22],'prompts'),group('Main route: three sessions',[2,3]),group('Opening question and what to listen for',[5,6],'example')],'Alternative timing options, repeated targets and vocabulary')
design('teacher',2,'Teach the three mechanisms clearly','Keep every explanation attached to the specific decision and the evidence supporting it.',[group('Begin with the bus display',[22,23,24],'example'),group('Explain the information path',[2,25]),group('Model: claim → evidence → limited conclusion',[31,32,33],'example'),group('Prevent the “all rules are non-AI” shortcut',[15,26]),group('Transfer the explanation to umbrellas',[37,39,40,41,42,44],'example'),group('Change the rule, not the forecast',[48,49,50],'steps'),group('Respect the limit',[46]),group('Use the picture deliberately',[35,52])],'Six-device key, vocabulary and additional explanation prompts')
design('teacher',3,'Model, then remove the help','Use the photo-library question to check whether learners can transfer the bus explanation.',[group('Prompt, then listen',[16],'example'),group('Reasoning to listen for',[17,18]),group('Check the misconception before discussion',[20,21,22],'example'),group('Use the umbrella picture as a quick check',[24,26,27,28]),group('Keep the dialogue focused',[7,8,10],'prompts')],'Earlier board sequence and alternative case-specific schedule')
design('teacher',4,'Run the device detective investigation','The device cards are supported practice. Reserve the greenhouse for the independent attempt.',[group('Organise the task',[3,4,5,6],'steps'),group('Keep an inspectable record',[10]),group('Diagnose the first misunderstanding',[15,16,17],'cards'),group('Choose the next teaching action',[19,20])],'Original lab setup, alternative workflow and general guidance')
design('teacher',5,'Assess the explanation, not the label','Use the selected greenhouse key after the first attempt. Keep the other tasks clearly identified as practice.',[group('Selected independent case: greenhouse',[31,33],'example'),group('Judge the evidence in the response',[34,35]),group('Give feedback the learner can use',[37]),group('Workbook W1: observation and mechanism',[16,17],'example'),group('Workbook W2: photo-library trace',[19,20],'example'),group('Workbook W3: competing explanations',[22,23],'example'),group('Workbook W5: evidence-card design',[28,29],'example')],'Other practice keys, repeated greenhouse copy and earlier scoring option')
design('teacher',6,'Connect, adapt and return later','Keep one useful project record, adapt access to the explanation, and plan a changed-case return check.',[group('Project evidence to keep',[2,3,20]),group('Remove barriers; retain the reasoning goal',[5,11,12]),group('Plan a later check',[15,16,17,18]),group('Connect to Week 2',[7,9,13])],'Original project and extension headings')
design('teacher',7,'Reference: alternative planning checklist','This repeats the main teaching cycle in checklist form. Use one planning route, not both.',[group('Preparation checklist',[0,1,2]),group('Practice, support and assessment reminders',list(range(3,13)))],'Original planning material',True)
design('teacher',8,'Reference: feedback and digital tools','Use tools to keep an explanation and its evidence. This week does not require a coding lab.',[group('Keep supported practice and assessment separate',[0,1]),group('Use repair and portfolio records',[3,4])],'Coding guidance for later weeks',True)
tg=[]
for n in range(6):tg.append(group(w['teacher'][8]['blocks'][1+5*n]['text'],list(range(2+5*n,6+5*n))))
design('teacher',9,'Reference: teach with the six pictures','Choose the picture that serves your next teaching move rather than presenting the gallery as a second lesson.',tg,'Whole-gallery teaching note',True)

# Workbook: one main response for each stage; duplicated versions remain labelled references.
wb=[(1,'Start: what did you observe?','Try before notes; keep your later correction visible.',[group('The speaking-clock puzzle',[0,1,2],'prompts')],False),(12,'W1 · Separate seeing from explaining','Use the door case to separate an observation from a question about its mechanism.',[group('Read, then explain',[0,1],'prompts')],False),(13,'W2 · Trace the photo-library decisions','Use the supplied facts to classify each decision and choose a useful diagnostic record.',[],False),(14,'W3 · Explain two possible mechanisms','One observed turn can have more than one explanation. Name evidence that would distinguish them.',[group('The vacuum challenge',[0,1],'prompts')],False),(4,'W4 · Apply the idea independently','The greenhouse is a new case. Write one first attempt before feedback.',[group('Read the new case, then explain',[1,2],'example'),group('Keep a fair record',[3])],False),(16,'W5 · Design an evidence card','Build one example that lets another person check your claim.',[group('Create and justify',[0,1],'prompts')],False),(9,'Project · Choose your sorter’s mechanism','Make one decision and attach the evidence behind it.',[group('Your design choice',[0,1,2],'prompts')],False),(17,'Feedback · Repair and return','Keep your first attempt, the repair and a different case to revisit.',[group('Your learning record',[0,1])],False),(10,'Finish · Check what you can explain','Judge each item using work you can point to.',[group('Your self-check',[0,1])],False)]
photo_facts=add('workbook',13,'Given facts: a photo library uses a model fitted on labelled pictures to predict whether a new picture contains a bicycle. A written instruction puts bicycle predictions in one album. The owner can move any photo. A bicycle photo is in the wrong album; the reason has not yet been identified.')
for n,title,purpose,gs,opt in wb:
 if n==13:gs=[group('The case facts',[photo_facts],'example'),group('Your trace and diagnosis',[0,1],'prompts')]
 design('workbook',n,title,purpose,gs,'Earlier wording and repeated headings',opt)
for n,title,purpose in [(2,'Reference · Record the help you used','This supplements W2; do not repeat the same completed explanation.'),(3,'Extra practice · Are all rules outside AI?','Try the claim before discussing it.'),(5,'Reference · The bus learning target','Use the bus explanation as a reminder, not a second independent assessment.'),(6,'Extra practice · Device detective record','Use these cards and this response space if you choose the six-device investigation.'),(7,'Extra practice · Toy, photo app and clock','Use this as a later changed case.'),(8,'Extra practice · Design a revealing test','Keep predicted and observed results separate.'),(11,'Reference · Revisit the bus question','This bus question has already been used in teaching; record it as practice.'),(15,'Reference · Greenhouse response copy','This is the same W4 case. Reuse its first-attempt record.'),(18,'Extra practice · Read the umbrella picture','Explain the stage and its changed boundary.'),(19,'Reference · Sorter portfolio record','Use alongside your main project response when you need a fuller record.'),(20,'Extra practice · Supported questions','Choose the paper or interactive version, and compare with feedback after trying.'),(21,'Reference · Six-picture response sheets','Choose a relevant picture; completing all six is optional.')]:
 s=w['workbook'][n-1]
 if n==21:gs=[group(s['blocks'][5*i]['text'],list(range(5*i+1,5*i+5))) for i in range(6)]
 elif n==20:gs=[group('First supported question',list(range(1,10)),'prompts'),group('Check after trying',[10],'example',collapsed=True),group('Changed boundary question',list(range(11,18)),'prompts'),group('Check after trying',[18],'example',collapsed=True),group('What you will keep',[20,22,23])]
 else:gs=[group('Use this when helpful',list(range(len(s['blocks']))))]
 design('workbook',n,title,purpose,gs,'Earlier prompts and notes',True)

overviews={
 'sections':('AI or Not? Follow the decision.','A red bus display, an umbrella forecast and a photo library all lead to one question: what produced this particular decision?','Explain the decision → point to its evidence → state what remains unknown.',[1,2,3,4,6,7,8,9,14,11,16,5,10,12,13,15,17,18],[('Notice',2),('Understand',3),('Compare',4),('Practise',8),('Try alone',14),('Build & reflect',11)]),
 'teacher':('Teach one connected idea.','Model the bus, transfer to umbrellas, guide the photo-library explanation, then reserve the greenhouse for independent evidence.','Look for a mechanism, the deciding fact, and a defensible limit.',list(range(1,10)),[('Prepare',1),('Explain',2),('Guide',3),('Investigate',4),('Assess',5),('Return',6)]),
 'workbook':('One week. One connected evidence record.','Use the main worksheets in order. The reference bank contains alternative copies and extra practice, so you can choose support without repeating the whole week.','Keep your first attempt, the evidence behind it and the correction you can explain.',[1,12,13,14,4,16,9,17,10,2,3,5,6,7,8,11,15,18,19,20,21],[('Recall',1),('Observe',12),('Trace',13),('Challenge',14),('Try alone',4),('Create',16)])}
for role,(title,lead,outcome,order,route) in overviews.items():
 w[role][0]['reading_flow']['overview']={'title':title,'lead':lead,'outcome':outcome,'order':order,'route':[{'label':label,'section':n} for label,n in route]}
for role in ['sections','teacher','workbook']:
 for before,after in zip(original[role],w[role]):assert before['blocks']==after['blocks'][:len(before['blocks'])]
p.write_text(json.dumps(d,ensure_ascii=False,indent=2))
(R/'reports/week1-connected-reading.json').write_text(json.dumps({'lesson':w['id'],'sections_reviewed':48,'original_blocks_preserved':True,'scope':'Only Level 1 Week 1; connected lesson path, authored section chunks, matched picture/text, primary workbook sequence and labelled reference bank.','roles':{role:{'main_sections':sum(not s['reading_flow']['optional'] for s in w[role]),'reference_sections':sum(s['reading_flow']['optional'] for s in w[role]),'sections':[{'title':s['reading_flow']['title'],'source_title':s['title'],'groups':[g['title'] for g in s['reading_flow']['groups']]} for s in w[role]]} for role in overviews}},ensure_ascii=False,indent=2))
print('Designed all48 Week1 sections. Original blocks and source positions retained; main route and reference bank authored separately.')
